import java.io.*;

// 实现 AutoCloseable 接口
class Box implements AutoCloseable {
    public void close() {
        System.out.println("Box closed!");
    }
}

public class Main {
    public static void main(String[] args) {
        // 在 try (...) 括号中声明资源
        try (Box box = new Box()) {
            System.out.println("Using Box...");
            throw new RuntimeException("Boom!");
        } catch (Exception e) {
            System.out.println("Caught: " + e.getMessage());
        }
    }
}
